def digest(data):
    return hashlib.sha256(data).hexdigest()

def checked_bytes(path,record):
    data=Path(path).read_bytes()
    if len(data)!=record['bytes'] or digest(data)!=record['sha256']:
        raise ValueError('Complete source bytes differ: '+str(path))
    return data

def transform(data,hunks,reverse=False):
    lines=data.decode('utf-8').split('\n')
    index='new_line' if reverse else 'old_line'
    before='new' if reverse else 'old'
    after='old' if reverse else 'new'
    for hunk in reversed(hunks):
        at=hunk[index]
        expected=hunk[before]
        if lines[at:at+len(expected)]!=expected:
            raise ValueError('The complete anchored source segment changed')
        lines[at:at+len(expected)]=hunk[after]
    return '\n'.join(lines).encode('utf-8')

def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('--repo',type=Path,required=True)
    p.add_argument('--output-dir',type=Path,required=True)
    p.add_argument('--verify-existing',action='store_true')
    args=p.parse_args()
    repo=args.repo.resolve()
    destination=args.output_dir.resolve()
    if destination==repo or repo in destination.parents:
        raise ValueError('Use a scratch destination, without editing repository sources or refs')
    if not args.verify_existing:
        destination.mkdir(parents=True,exist_ok=True)
    for record in SHARED:
        checked_bytes(repo/record['path'],record)
    records=[]
    for item in SPEC:
        original=checked_bytes(repo/item['parent']['path'],item['parent'])
        produced=transform(original,item['hunks'])
        record=item['output']
        if len(produced)!=record['bytes'] or digest(produced)!=record['sha256']:
            raise ValueError('The complete reproduced source differs: '+record['name'])
        if transform(produced,item['hunks'],reverse=True)!=original:
            raise ValueError('Complete reverse reconstruction differs: '+record['name'])
        output=destination/record['name']
        if args.verify_existing or output.exists():
            checked_bytes(output,record)
        else:
            output.write_bytes(produced)
            checked_bytes(output,record)
        records.append(dict(name=record['name'],bytes=record['bytes'],sha256=record['sha256'],
            original_complete_source_sha256=item['parent']['sha256'],
            forward_and_inverse_complete_source_bytes_checked=True))
    print(json.dumps(dict(schema='complete-fixed-fejer-J1845-source-reproduction-v1',
        source_sha256=digest(Path(__file__).read_bytes()),complete_sources=records,
        generated_modules_imported=False,scientific_execution_performed=False,
        repository_refs_modified=False),sort_keys=True,allow_nan=False))

if __name__=='__main__':
    main()
